import com.iocextractor.observability.LogField;
import com.iocextractor.observability.MdcScope;
import java.lang.management.ManagementFactory;
import org.slf4j.MDC;
public class O5MdcProbe {
  static void scope() {
    try (var ignored = MdcScope.open().put(LogField.IOC_ROUTER_PLAN, "plan")
        .hide(LogField.IOC_ROUTER_BRANCH).put(LogField.IOC_ROUTER_VIEW, "host")) {
      if (!"host".equals(MDC.get(LogField.IOC_ROUTER_VIEW.key()))) throw new AssertionError("view");
    }
    if (!"ambient".equals(MDC.get(LogField.IOC_ROUTER_PLAN.key()))) throw new AssertionError("restore");
  }
  public static void main(String[] args) {
    MDC.put(LogField.IOC_ROUTER_PLAN.key(), "ambient");
    for (int i=0;i<20000;i++) scope();
    var bean = (com.sun.management.ThreadMXBean) ManagementFactory.getThreadMXBean();
    long id = Thread.currentThread().threadId(), start = bean.getThreadAllocatedBytes(id), time=System.nanoTime();
    for (int i=0;i<100000;i++) scope();
    System.out.println("MDC_PROBE bytes="+(bean.getThreadAllocatedBytes(id)-start)+" nanos="+(System.nanoTime()-time));
    MDC.clear();
  }
}
